import React from 'react';

const Profile = () => {
  const user = JSON.parse(localStorage.getItem('user'));
  if (!user) return <div style={{ textAlign: 'center', marginTop: 40 }}>Not signed in.</div>;

  return (
    <section className="container" style={{ maxWidth: 400, margin: '60px auto' }}>
      <div className="card">
        <h2 style={{ textAlign: 'center', marginBottom: 24 }}>Profile</h2>
        <div><strong>Name:</strong> {user.name}</div>
        <div><strong>Email:</strong> {user.email}</div>
        {/* Add more profile management features here */}
      </div>
    </section>
  );
};

export default Profile;
